/* Equipment art generated with GPT Image. Native 1254-square art is padded,
 * never enlarged, into one mipmapped 2048 texture for WebGL 1 compatibility. */
window.astraSceneryReady=new Promise((resolve,reject)=>{
  const image=new Image();image.onerror=()=>reject(Error('Could not decode equipment artwork'));
  image.onload=()=>{
    const canvas=document.createElement('canvas');canvas.width=canvas.height=2048;
    const ctx=canvas.getContext('2d');ctx.fillStyle='#10171b';ctx.fillRect(0,0,2048,2048);ctx.drawImage(image,0,0);
    canvas.toBlob(async blob=>{try{if(!blob)throw Error('Could not prepare equipment artwork');const bytes=new Uint8Array(await blob.arrayBuffer());canvas.width=canvas.height=1;resolve(bytes);}catch(e){reject(e);}},'image/png');
  };
  image.src='data:image/jpeg;base64,';
});
